"""Synonym and full-form seeds for each service, generated by the model per run.

The model is always mocked. These tests pin down:
- synonyms are added right after the service's own seed, tagged with their origin;
- duplicates (of the root, of existing seeds, of each other, of another selected
  service) are skipped;
- a failing, slow, missing or confused model leaves the service seeded by its own name;
- one run asks the model once per service, however often and however concurrently the
  service is asked for.
"""

import asyncio
from unittest.mock import AsyncMock, patch

import pytest

from app.services.keyword_relevance import build_relevance_context
from app.services.seed_synonyms import (
    MAX_SYNONYMS,
    SeedSynonymResolver,
    audit_entries,
    clean_synonyms,
    generator,
    operator_notice,
)
from app.services.seed_synonyms.prompts import (
    EXAMPLES,
    EXAMPLES_BY_INDUSTRY,
    SYSTEM_PROMPT,
    build_user_prompt,
)
from app.services.service_seeding import (
    SYNONYM_ORIGIN,
    extra_seeds_last,
    generate_service_seeds,
    plan_service_seeds,
    related_seed_pairs,
    round_robin_seeds,
    run_service_scoped_seeding,
)

CONFIRMED = "2026-10-01T00:00:00+00:00"


class FakeModel:
    """Stands in for the LLM call: answers per service and counts the calls."""

    def __init__(self, answers=None, *, error=None, delay=0.0):
        self.answers = answers or {}
        self.error = error
        self.delay = delay
        self.calls: list[str] = []

    async def __call__(self, service, **context):
        self.calls.append(service)
        if self.delay:
            await asyncio.sleep(self.delay)
        if self.error is not None:
            raise self.error
        return {"synonyms": list(self.answers.get(service, []))}


def _seo_catalog():
    return [
        {
            "id": "seo",
            "name": "SEO",
            "source": "website",
            "subservices": [
                {"id": "local seo", "name": "Local SEO", "source": "website"},
                {"id": "technical seo", "name": "Technical SEO", "source": "website"},
            ],
        },
        {"id": "meta ads", "name": "Meta Ads", "source": "website", "subservices": []},
    ]


def _prio(*ids):
    return {"confirmed_at": CONFIRMED, "selected_service_ids": list(ids)}


# ------------------------------------------------------------------- the module


async def test_model_synonyms_are_cleaned_and_capped():
    model = FakeModel(
        {
            "SEO": [
                "Search Engine Optimisation",
                "organic search",
                "SEO",  # the service itself
                "what is seo",  # a question, not a name
                "seo company",  # the service's name with a qualifier
                "search engine ranking",
                "  organic search ",  # repeat
                "google ranking",
                "search visibility",
                "search optimisation",
                "website ranking",  # a seventh usable one: over the cap
            ]
        }
    )
    result = await SeedSynonymResolver(ask=model).synonyms_for("SEO")
    assert result.status == "ok"
    assert result.synonyms == (
        "search engine optimisation",
        "organic search",
        "search engine ranking",
        "google ranking",
        "search visibility",
        "search optimisation",
    )
    assert MAX_SYNONYMS == 6
    assert len(result.synonyms) <= MAX_SYNONYMS


@pytest.mark.parametrize(
    ("service", "phrases", "kept"),
    [
        # a qualifier on the service's own name is not an alternate name
        ("SEO", ["best seo", "seo company", "top seo agency", "seo near me", "seo firm"], []),
        # the full service name with "services" stuck on is the same search
        (
            "Email Marketing",
            [
                "email marketing services",
                "email campaigns",
                "email automation",
                "email campaign management",
                "email newsletters",
                "edm marketing",
            ],
            ["email campaigns", "email automation", "email newsletters", "edm marketing"],
        ),
        (
            "Social Media Marketing",
            [
                "social media marketing services",
                "smm services",
                "social media management",
                "social media advertising",
                "social media strategy",
            ],
            ["smm", "social media management", "social media advertising", "social media strategy"],
        ),
        # "near me" is never a name for the service, whatever it is attached to
        ("Electrical", ["electrician near me", "electrical services"], ["electrical services"]),
        # "services" / "solutions" are how people name some services (their examples)
        (
            "Catering",
            ["food catering", "catering services", "catering solutions", "catering company"],
            ["food catering", "catering services", "catering solutions"],
        ),
        (
            "web development",
            ["professional web development", "web development company", "custom website", "web design"],
            ["custom website", "web design"],
        ),
        # the same applies to a phrase already kept
        (
            "SEO",
            ["search engine optimisation", "best search engine optimisation", "organic search"],
            ["search engine optimisation", "organic search"],
        ),
        # a different name that happens to contain an everyday word is kept
        ("ecommerce", ["online store", "ecommerce website", "shopify development"], ["online store", "ecommerce website", "shopify development"]),
        # a service whose own name carries a qualifier: the bare name is the same service
        ("SEO Agency", ["seo", "organic search"], ["organic search"]),
    ],
)
def test_modifier_variants_are_not_alternate_names(service, phrases, kept):
    assert clean_synonyms(service, phrases) == kept


def test_plural_forms_of_the_service_or_of_a_kept_phrase_are_repeats():
    # Both came back from the live model; the root's own fetch already finds them.
    assert clean_synonyms(
        "Roof Repair", ["roof repairs", "roof leak repair", "roofing repairs", "roof repair company"]
    ) == ["roof leak repair", "roofing repairs"]
    assert clean_synonyms(
        "Bridging Finance", ["bridging loan", "bridging loans", "bridge loan finance"]
    ) == ["bridging loan", "bridge loan finance"]


def test_phrases_over_five_words_are_dropped():
    assert clean_synonyms("SEO", ["search engine optimisation for small local businesses"]) == []
    # exactly five words is allowed
    assert clean_synonyms("SEO", ["google search engine ranking help"]) == ["google search engine ranking help"]


async def test_the_examples_are_a_pattern_not_a_lookup_table():
    # SEO is one of the prompt's examples, yet the answer is whatever the model says,
    # and a service from another industry is asked about the same way.
    model = FakeModel(
        {
            "SEO": ["organic search marketing"],
            "Roof Repair": ["roof leak repair", "roofing repair", "leaking roof fix"],
        }
    )
    resolver = SeedSynonymResolver(ask=model)
    assert (await resolver.synonyms_for("SEO")).synonyms == ("organic search marketing",)
    assert (await resolver.synonyms_for("Roof Repair")).synonyms == (
        "roof leak repair",
        "roofing repair",
        "leaking roof fix",
    )
    assert model.calls == ["SEO", "Roof Repair"]


async def test_the_llm_call_gets_the_prompt_and_the_business_context():
    llm = AsyncMock(
        return_value='{"synonyms": ["search engine optimisation", "organic search"]}'
    )
    with patch.object(generator, "keyword_analysis_chat", llm):
        result = await SeedSynonymResolver(
            industry="digital marketing agency",
            market="Australia",
            other_services=["SEO", "Meta Ads"],
        ).synonyms_for("SEO")
    assert result.synonyms == ("search engine optimisation", "organic search")
    llm.assert_awaited_once()
    system = llm.await_args.kwargs["system"]
    user = llm.await_args.kwargs["user"]
    assert system.startswith(SYSTEM_PROMPT)
    assert "Service: SEO" in user
    assert "Business industry: digital marketing agency" in user
    assert "Market: Australia" in user
    assert "Meta Ads" in user and "(these are not synonyms): SEO" not in user


def test_the_prompt_teaches_the_pattern_and_the_limits():
    for service, phrases in EXAMPLES:
        assert f"{service} -> {', '.join(phrases)}" in SYSTEM_PROMPT
    assert len(EXAMPLES) == 28
    assert {industry for industry, _ in EXAMPLES_BY_INDUSTRY} == {
        "Digital marketing", "Legal", "Finance", "Healthcare", "Trades", "Education", "Real estate", "Hospitality",
    }
    for industry, _pairs in EXAMPLES_BY_INDUSTRY:
        assert f"{industry}:" in SYSTEM_PROMPT
    assert dict(EXAMPLES)["SEO"] == (
        "search engine optimisation",
        "organic search",
        "google ranking",
        "search visibility",
    )
    assert dict(EXAMPLES)["Family Law"][0] == "divorce law"
    assert all(3 <= len(phrases) <= 4 for _, phrases in EXAMPLES)
    assert "Return 4 to 6 names" in SYSTEM_PROMPT
    assert "never more than 6" in SYSTEM_PROMPT
    assert "types into Google" in SYSTEM_PROMPT
    assert "distinct search" in SYSTEM_PROMPT
    assert "company, agency, firm, near me" in SYSTEM_PROMPT
    assert "email marketing services" in SYSTEM_PROMPT
    assert "email campaign management" in SYSTEM_PROMPT
    assert "Not a sub-service" in SYSTEM_PROMPT
    assert "over-broad" in SYSTEM_PROMPT
    assert "at most 5 words" in SYSTEM_PROMPT
    assert "real search volume" in SYSTEM_PROMPT
    assert "Nothing invented" in SYSTEM_PROMPT
    assert "any service in any industry" in SYSTEM_PROMPT
    user = build_user_prompt("CRO", industry=None, market=None, other_services=["CRO"])
    assert "Business industry: not given" in user
    assert "Other services" not in user  # the service itself is not "another" service


# ------------------------------------------------------------------------ cache


async def test_one_run_asks_the_model_once_per_service():
    model = FakeModel({"SEO": ["search engine optimization"]})
    resolver = SeedSynonymResolver(ask=model)
    first = await resolver.synonyms_for("SEO")
    second = await resolver.synonyms_for("SEO")
    third = await resolver.synonyms_for("  seo ")  # the same name, typed differently
    assert model.calls == ["SEO"]
    assert resolver.llm_calls == 1
    assert first.cached is False and second.cached is True and third.cached is True
    assert first.synonyms == second.synonyms == third.synonyms


async def test_concurrent_requests_for_one_service_share_one_call():
    model = FakeModel({"SEO": ["search engine optimization"]}, delay=0.05)
    resolver = SeedSynonymResolver(ask=model)
    results = await asyncio.gather(*(resolver.synonyms_for("SEO") for _ in range(5)))
    assert model.calls == ["SEO"]
    assert all(r.synonyms == ("search engine optimization",) for r in results)


async def test_resolve_all_asks_once_per_distinct_service():
    model = FakeModel({"SEO": ["organic search"], "Meta Ads": ["facebook ads"]})
    resolver = SeedSynonymResolver(ask=model)
    results = await resolver.resolve_all(["SEO", "Meta Ads", "SEO", "seo"])
    assert sorted(model.calls) == ["Meta Ads", "SEO"]
    assert results["SEO"].synonyms == ("organic search",)
    assert results["Meta Ads"].synonyms == ("facebook ads",)


async def test_a_new_run_asks_again():
    model = FakeModel({"SEO": ["organic search"]})
    await SeedSynonymResolver(ask=model).synonyms_for("SEO")
    await SeedSynonymResolver(ask=model).synonyms_for("SEO")
    assert model.calls == ["SEO", "SEO"]


# --------------------------------------------------------------------- fallback


async def test_a_failing_model_falls_back_without_raising():
    model = FakeModel(error=RuntimeError("anthropic 529 overloaded"))
    with patch.object(generator, "_provider_ready", return_value=True):
        result = await SeedSynonymResolver(ask=model).synonyms_for("SEO")
    assert result.synonyms == ()
    assert result.status == "llm_failed"
    assert "overloaded" in (result.error or "")


async def test_ask_model_retries_on_the_keyword_analysis_fallback():
    chat = AsyncMock(
        return_value='{"synonyms": ["search engine optimisation", "organic search"]}'
    )
    with patch.object(generator, "keyword_analysis_chat", chat):
        reply = await generator.ask_model("SEO", industry="Digital marketing")
    assert reply["synonyms"] == ["search engine optimisation", "organic search"]
    chat.assert_awaited_once()
    assert "SEO" in chat.await_args.kwargs["user"]


async def test_a_missing_model_is_reported_as_unavailable():
    # The suite runs with USE_MOCK_LLM, exactly like a deployment with no Anthropic key.
    result = await SeedSynonymResolver().synonyms_for("SEO")
    assert result.synonyms == ()
    assert result.status == "llm_unavailable"


async def test_a_slow_model_times_out_and_falls_back():
    model = FakeModel({"SEO": ["organic search"]}, delay=1.0)
    result = await SeedSynonymResolver(ask=model, timeout=0.05).synonyms_for("SEO")
    assert result.status == "timeout"
    assert result.synonyms == ()


async def test_a_failure_is_remembered_so_the_run_never_waits_twice():
    model = FakeModel({"SEO": ["organic search"]}, delay=1.0)
    resolver = SeedSynonymResolver(ask=model, timeout=0.05)
    await resolver.synonyms_for("SEO")
    again = await resolver.synonyms_for("SEO")
    assert model.calls == ["SEO"]
    assert again.status == "timeout" and again.cached is True


async def test_an_unusable_reply_falls_back():
    async def confused(service, **context):
        return {"answer": "SEO is search engine optimization"}

    result = await SeedSynonymResolver(ask=confused).synonyms_for("SEO")
    assert result.status == "invalid_reply"
    assert result.synonyms == ()


async def test_model_failure_leaves_just_the_service_name_as_its_seed():
    model = FakeModel(error=TimeoutError("read timed out"))
    results = await SeedSynonymResolver(ask=model).resolve_all(["SEO"])
    plans = plan_service_seeds(
        ["SEO"],
        pool_roots=[],
        pool_targets={},
        catalog=[],
        prioritization={},
        service_synonyms={name: r.synonyms for name, r in results.items()},
    )
    assert plans[0].seeds == ["SEO"]
    assert plans[0].synonyms_added == []


# ---------------------------------------------------------- seed generation


def test_synonyms_are_added_right_after_the_service_root_and_tagged():
    # Every other kind of seed the service can have: a sub-service page on the site,
    # a business keyword, and the offered sub-services from the catalog.
    pool_roots = ["seo audit", "seo melbourne"]
    pool_targets = {
        "seo audit": {"target": "SEO Audit", "target_type": "sub_service", "parent_segment": "SEO"},
        "seo melbourne": {"target": "seo melbourne", "target_type": "keyword"},
    }
    plan = generate_service_seeds(
        "SEO",
        pool_roots=pool_roots,
        pool_targets=pool_targets,
        catalog=_seo_catalog(),
        prioritization=_prio("seo"),
        synonyms=["search engine optimization", "organic search"],
    )
    # Root, its synonyms, then the catalog's offered sub-services as seeds of their
    # own (2026-10-27). The sub-service page in the pool is still not a seed.
    assert plan.seeds == [
        "SEO", "search engine optimization", "organic search", "Local SEO", "Technical SEO",
    ]
    assert "seo audit" not in plan.seed_targets
    for synonym in ("search engine optimization", "organic search"):
        meta = plan.seed_targets[synonym]
        assert meta["seed_origin"] == SYNONYM_ORIGIN
        assert meta["synonym_of"] == "SEO"
        assert meta["service"] == "SEO"
        assert meta["target"] == "SEO"
        assert meta["target_type"] == "service"
    assert "seed_origin" not in plan.seed_targets["seo"]
    assert plan.synonyms_added == ["search engine optimization", "organic search"]


def test_duplicate_synonyms_are_skipped():
    pool_roots = ["seo melbourne"]
    pool_targets = {"seo melbourne": {"target": "seo melbourne", "target_type": "keyword"}}
    plan = generate_service_seeds(
        "SEO",
        pool_roots=pool_roots,
        pool_targets=pool_targets,
        catalog=_seo_catalog(),
        prioritization=_prio("seo"),
        other_service_names=["SEO", "Meta Ads"],
        synonyms=[
            "seo",  # the root itself
            "local seo",  # a sub-service, not a seed
            "search engine optimization",
            "Search Engine Optimization",  # repeat of the one just added
            "meta ads",  # another selected service's own name
        ],
    )
    assert plan.synonyms_added == ["search engine optimization"]
    reasons = {(s["phrase"], s["reason"]) for s in plan.synonyms_skipped}
    assert reasons == {
        ("seo", "duplicate"),
        ("local seo", "sub_service"),
        ("Search Engine Optimization", "duplicate"),
        ("meta ads", "another_service"),
    }
    lowered = [s.lower() for s in plan.seeds]
    assert len(lowered) == len(set(lowered))
    # "local seo" is not a synonym of SEO; it is seeded as its own sub-service.
    assert plan.seed_targets["local seo"]["target_type"] == "sub_service"
    assert plan.seed_targets["local seo"]["parent_segment"] == "SEO"
    assert "local seo" not in plan.synonyms_added
    assert "seo melbourne" not in plan.seed_targets


def test_synonyms_go_through_the_same_seed_validation_as_any_seed():
    plan = generate_service_seeds(
        "SEO",
        pool_roots=[],
        pool_targets={},
        catalog=[],
        prioritization={},
        is_brand=lambda term: "rankmasters" in term.lower(),
        synonyms=[
            "seo 2019",  # stale year
            "rankmasters seo",  # a competitor's brand
            "x",  # too short
            "search engine optimisation & marketing",  # cleaned like any seed
        ],
    )
    assert plan.synonyms_added == ["search engine optimisation marketing"]
    assert {s["phrase"] for s in plan.synonyms_skipped if s["reason"] == "invalid_seed"} == {
        "seo 2019",
        "rankmasters seo",
        "x",
    }


