def test_each_service_only_gets_its_own_synonyms():
    plans = plan_service_seeds(
        ["SEO", "Meta Ads"],
        pool_roots=[],
        pool_targets={},
        catalog=_seo_catalog(),
        prioritization=_prio("seo", "meta ads"),
        service_synonyms={
            "SEO": ["search engine optimization", "organic search"],
            "meta ads": ["facebook advertising", "meta advertising"],  # name typed differently
        },
    )
    by_service = {p.service: p for p in plans}
    assert by_service["SEO"].synonyms_added == ["search engine optimization", "organic search"]
    assert by_service["Meta Ads"].synonyms_added == ["facebook advertising", "meta advertising"]
    assert not set(by_service["SEO"].seeds) & {"facebook advertising", "meta advertising"}
    assert not set(by_service["Meta Ads"].seeds) & {"search engine optimization", "organic search"}


# ------------------------------------------------------------------- budget


class RecordingFetch:
    def __init__(self):
        self.calls: list[dict] = []

    async def __call__(self, seeds, *, seed_targets=None, **kw):
        service = next(iter((seed_targets or {}).values()), {}).get("service", "?")
        self.calls.append({"service": service, "seeds": list(seeds)})
        return {"seeds": list(seeds), "seed_clusters": [], "keyword_dataset": [], "keyword_count": 0}


async def test_synonyms_never_push_a_sub_service_out_of_the_budget():
    common = {
        "pool_roots": [],
        "pool_targets": {},
        "catalog": _seo_catalog(),
        "prioritization": _prio("seo", "meta ads"),
    }
    without = plan_service_seeds(["SEO", "Meta Ads"], **common)
    with_synonyms = plan_service_seeds(
        ["SEO", "Meta Ads"],
        **common,
        service_synonyms={"SEO": ["search engine optimization", "organic search", "search optimization"]},
    )

    async def fetched(plans):
        fetch = RecordingFetch()
        await run_service_scoped_seeding(plans, fetch=fetch, total_cap=3)
        return {c["service"]: c["seeds"] for c in fetch.calls}

    base = await fetched(without)
    extra = await fetched(with_synonyms)
    # every seed the service had without synonyms is still fetched...
    assert set(base["SEO"]) <= set(extra["SEO"])
    assert base["Meta Ads"] == extra["Meta Ads"]
    # ...and the synonyms come on top, right after the root
    assert extra["SEO"][:4] == ["SEO", "search engine optimization", "organic search", "search optimization"]
    assert len(extra["SEO"]) == len(base["SEO"]) + 3


def test_related_lookups_use_a_services_own_seeds_before_its_synonyms():
    plans = plan_service_seeds(
        ["SEO"],
        pool_roots=[],
        pool_targets={},
        catalog=_seo_catalog(),
        prioritization=_prio("seo"),
        service_synonyms={"SEO": ["search engine optimization"]},
    )
    runs = [{"service": "SEO", "seeds": plans[0].seeds}]
    picked = [seed for _service, seed in round_robin_seeds(extra_seeds_last(runs, plans), 2)]
    assert picked == ["SEO", "search engine optimization"]
    # The related step raises the cap by the sub-service seeds instead of spending it.
    pairs = [seed for _service, seed in related_seed_pairs(runs, plans, 2)]
    assert pairs == ["SEO", "search engine optimization", "Local SEO", "Technical SEO"]


# ---------------------------------------------------------------- relevance


def test_a_synonym_counts_as_its_service_when_judging_relevance():
    without = build_relevance_context(services=["SEO"])
    with_synonyms = build_relevance_context(
        services=["SEO"], service_synonyms=["search engine optimization"]
    )
    assert not without.seed_is_supported("search engine optimization")
    assert with_synonyms.seed_is_supported("search engine optimization")
    assert with_synonyms.seed_is_service("search engine optimization")
    # whole phrases only: the synonym's single words do not widen the gate
    assert with_synonyms.distinctive_tokens == without.distinctive_tokens
    assert with_synonyms.evidence_tokens == without.evidence_tokens


# -------------------------------------------------------------------- audit


async def test_audit_and_notice_say_what_happened_per_service():
    model = FakeModel({"SEO": ["search engine optimization", "seo"]})
    resolver = SeedSynonymResolver(ask=model)
    results = await resolver.resolve_all(["SEO"])
    slow = SeedSynonymResolver(ask=FakeModel(delay=1.0), timeout=0.05)
    results.update(await slow.resolve_all(["Meta Ads"]))
    plans = plan_service_seeds(
        ["SEO", "Meta Ads"],
        pool_roots=[],
        pool_targets={},
        catalog=[],
        prioritization={},
        service_synonyms={name: r.synonyms for name, r in results.items()},
    )
    entries = audit_entries(results, plans)
    by_service = {e["service"]: e for e in entries}
    assert by_service["SEO"]["status"] == "ok"
    assert by_service["SEO"]["added"] == ["search engine optimization"]
    assert by_service["Meta Ads"]["status"] == "timeout"
    assert by_service["Meta Ads"]["added"] == []
    notice = operator_notice(entries)
    assert "SEO +1 (search engine optimization)" in notice
    assert "Meta Ads: model timed out, seeded by its own name only" in notice


@pytest.mark.parametrize("status", ["llm_unavailable", "llm_failed", "invalid_reply", "no_synonyms"])
def test_every_fallback_is_named_in_the_notice(status):
    notice = operator_notice([{"service": "SEO", "status": status, "added": []}])
    assert notice.startswith("Synonym seeds: SEO: ")
    assert notice.endswith("seeded by its own name only.")
